# Populate Homebrew (`oz.rb`) and Windows winget (`OzoneVCS.Ozone*.yaml`)
# release manifests from a real `SHA256SUMS.txt` generated by release builds.

from __future__ import annotations

import argparse
import pathlib
import re
import sys
import tomllib

ZERO_SHA256 = "0" * 64
HEX64_RE = re.compile(r"^[0-9a-fA-F]{64}$")
VERSION_RE = re.compile(r"^[0-9]+\.[0-9]+\.[0-9]+([-.+][0-9A-Za-z.+-]+)?$")
SUMS_LINE_RE = re.compile(r"^\s*([0-9a-fA-F]{64})\s+\*?(\S+)\s*$")

HOMEBREW_TARGETS = (
    "aarch64-apple-darwin",
    "x86_64-apple-darwin",
    "aarch64-unknown-linux-gnu",
    "x86_64-unknown-linux-gnu",
)
WINDOWS_TARGET = "x86_64-pc-windows-msvc"


def read_cargo_version(repo_root: pathlib.Path) -> str:
    cargo_toml = repo_root / "Cargo.toml"
    with cargo_toml.open("rb") as f:
        data = tomllib.load(f)
    return str(data["workspace"]["package"]["version"])


def parse_checksums(path: pathlib.Path) -> dict[str, str]:
    if not path.is_file():
        raise SystemExit(f"error: checksums file not found: {path}")

    checksums: dict[str, str] = {}
    for lineno, raw_line in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        line = raw_line.strip()
        if not line:
            continue
        m = SUMS_LINE_RE.match(line)
        if not m:
            raise SystemExit(
                f"error: malformed SHA256SUMS line {lineno} in {path}: {raw_line!r}"
            )
        digest = m.group(1).lower()
        filename = m.group(2)
        if digest == ZERO_SHA256:
            raise SystemExit(
                f"error: refusing all-zero placeholder SHA256 for {filename} in {path}"
            )
        if filename in checksums and checksums[filename] != digest:
            raise SystemExit(
                f"error: conflicting SHA256 entries for {filename} in {path}"
            )
        checksums[filename] = digest

    return checksums


def require_release_checksums(checksums: dict[str, str], version: str) -> tuple[dict[str, str], str]:
    missing: list[str] = []
    hb_hashes: dict[str, str] = {}
    for target in HOMEBREW_TARGETS:
        archive = f"oz-v{version}-{target}.tar.gz"
        digest = checksums.get(archive)
        if not digest:
            missing.append(archive)
        else:
            hb_hashes[target] = digest.lower()

    win_archive = f"oz-v{version}-{WINDOWS_TARGET}.zip"
    win_digest = checksums.get(win_archive)
    if not win_digest:
        missing.append(win_archive)

    if missing:
        raise SystemExit(
            f"error: missing required release archives in checksums file for v{version}: "
            + ", ".join(missing)
        )

    assert win_digest is not None
    return hb_hashes, win_digest.upper()


def sub_exact(pattern: str, repl: str, text: str, expected: int, label: str) -> str:
    updated, count = re.subn(pattern, repl, text, flags=re.MULTILINE)
    if count != expected:
        raise SystemExit(
            f"error: expected {expected} match(es) for {label}, found {count}"
        )
    return updated


def populate_homebrew(
    template_path: pathlib.Path,
    out_path: pathlib.Path,
    version: str,
    hb_hashes: dict[str, str],
) -> None:
    text = template_path.read_text(encoding="utf-8")

    # Replace template header note with release-specific metadata comment if present.
    text = re.sub(
        r"(?m)^# Template Homebrew formula for Ozone \(oz / git-ozone / oz-vfsd\)\.$",
        f"# Homebrew formula for Ozone v{version} (oz / git-ozone / oz-vfsd).",
        text,
    )
    text = re.sub(
        r"(?m)^  # Template checksums are populated from SHA256SUMS\.txt by \.github/workflows/release\.yml\.$",
        f"  # Release checksums populated from SHA256SUMS.txt for v{version}.",
        text,
    )

    text = sub_exact(
        r'^(\s*version\s+")[^"]+(")$',
        rf"\g<1>{version}\g<2>",
        text,
        expected=1,
        label="Homebrew formula version",
    )

    for target, digest in hb_hashes.items():
        if not HEX64_RE.fullmatch(digest) or digest == ZERO_SHA256:
            raise SystemExit(f"error: invalid SHA256 for {target}: {digest}")
        url_sha_pat = (
            r'(url\s+"https://github\.com/Gaalix/git-ozone/releases/download/v#\{version\}/'
            rf'oz-v#\{{version\}}-{re.escape(target)}\.tar\.gz"\s*\n\s*sha256\s+")[0-9a-fA-F]{{64}}(")'
        )
        text = sub_exact(
            url_sha_pat,
            rf"\g<1>{digest}\g<2>",
            text,
            expected=1,
            label=f"Homebrew sha256 for {target}",
        )

    if ZERO_SHA256 in text:
        raise SystemExit(
            f"error: populated Homebrew formula still contains all-zero placeholder SHA256: {out_path}"
        )

    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(text, encoding="utf-8")


def populate_winget(
    template_dir: pathlib.Path,
    out_dir: pathlib.Path,
    version: str,
    win_digest_upper: str,
) -> None:
    if not HEX64_RE.fullmatch(win_digest_upper) or win_digest_upper == ZERO_SHA256:
        raise SystemExit(f"error: invalid Windows SHA256: {win_digest_upper}")

    ver_src = template_dir / "OzoneVCS.Ozone.yaml"
    inst_src = template_dir / "OzoneVCS.Ozone.installer.yaml"
    loc_src = template_dir / "OzoneVCS.Ozone.locale.en-US.yaml"
    for p in (ver_src, inst_src, loc_src):
        if not p.is_file():
            raise SystemExit(f"error: missing winget template: {p}")

    ver_text = sub_exact(
        r"^(PackageVersion:\s*)\S+$",
        rf"\g<1>{version}",
        ver_src.read_text(encoding="utf-8"),
        expected=1,
        label="winget version PackageVersion",
    )

    loc_text = sub_exact(
        r"^(PackageVersion:\s*)\S+$",
        rf"\g<1>{version}",
        loc_src.read_text(encoding="utf-8"),
        expected=1,
        label="winget locale PackageVersion",
    )
    loc_text = sub_exact(
        r"^(ReleaseNotesUrl:\s*https://github\.com/Gaalix/git-ozone/releases/tag/v)\S+$",
        rf"\g<1>{version}",
        loc_text,
        expected=1,
        label="winget locale ReleaseNotesUrl",
    )

    inst_text = inst_src.read_text(encoding="utf-8")
    inst_text = re.sub(
        r"(?m)^# Template manifest:.*$",
        f"# Generated from SHA256SUMS.txt for Ozone v{version}.",
        inst_text,
    )
    inst_text = sub_exact(
        r"^(PackageVersion:\s*)\S+$",
        rf"\g<1>{version}",
        inst_text,
        expected=1,
        label="winget installer PackageVersion",
    )
    inst_text = sub_exact(
        r"(RelativeFilePath:\s*)oz-v[^\\\s]+-x86_64-pc-windows-msvc\\",
        rf"\g<1>oz-v{version}-{WINDOWS_TARGET}\\",
        inst_text,
        expected=3,
        label="winget NestedInstallerFiles RelativeFilePath",
    )
    expected_win_url = (
        f"https://github.com/Gaalix/git-ozone/releases/download/v{version}/"
        f"oz-v{version}-{WINDOWS_TARGET}.zip"
    )
    inst_text = sub_exact(
        r"^(\s*InstallerUrl:\s*)https://github\.com/Gaalix/git-ozone/releases/download/v\S+/oz-v\S+-x86_64-pc-windows-msvc\.zip$",
        rf"\g<1>{expected_win_url}",
        inst_text,
        expected=1,
        label="winget InstallerUrl",
    )
    inst_text = sub_exact(
        r'^(\s*InstallerSha256:\s*)"?[0-9a-fA-F]{64}"?$',
        rf'\g<1>"{win_digest_upper}"',
        inst_text,
        expected=1,
        label="winget InstallerSha256",
    )

    if ZERO_SHA256 in inst_text:
        raise SystemExit(
            "error: populated winget installer manifest still contains all-zero placeholder SHA256"
        )

    # Verify generated YAML syntax & field invariants when PyYAML is available.
    try:
        import yaml  # type: ignore
    except ImportError:
        yaml = None

    if yaml is not None:
        parsed_ver = yaml.safe_load(ver_text)
        parsed_loc = yaml.safe_load(loc_text)
        parsed_inst = yaml.safe_load(inst_text)
        if parsed_ver.get("PackageVersion") != version:
            raise SystemExit("error: generated winget version YAML PackageVersion mismatch")
        if parsed_loc.get("PackageVersion") != version:
            raise SystemExit("error: generated winget locale YAML PackageVersion mismatch")
        if parsed_inst.get("PackageVersion") != version:
            raise SystemExit("error: generated winget installer YAML PackageVersion mismatch")
        inst_entry = parsed_inst["Installers"][0]
        if inst_entry.get("InstallerUrl") != expected_win_url:
            raise SystemExit("error: generated winget InstallerUrl mismatch")
        if inst_entry.get("InstallerSha256") != win_digest_upper:
            raise SystemExit("error: generated winget InstallerSha256 mismatch")

    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / "OzoneVCS.Ozone.yaml").write_text(ver_text, encoding="utf-8")
    (out_dir / "OzoneVCS.Ozone.installer.yaml").write_text(inst_text, encoding="utf-8")
    (out_dir / "OzoneVCS.Ozone.locale.en-US.yaml").write_text(loc_text, encoding="utf-8")


def main() -> int:
    repo_root = pathlib.Path(__file__).resolve().parent.parent

    parser = argparse.ArgumentParser(
        description="Populate Ozone Homebrew and winget manifests from SHA256SUMS.txt."
    )
    parser.add_argument(
        "--version",
        help="Release version (e.g. 1.3.0 or v1.3.0; defaults to Cargo.toml workspace version)",
    )
    parser.add_argument(
        "--checksums",
        required=True,
        type=pathlib.Path,
        help="Path to SHA256SUMS.txt generated for the release archives",
    )
    parser.add_argument(
        "--homebrew-template",
        type=pathlib.Path,
        default=repo_root / "packaging/homebrew/oz.rb",
        help="Path to template Homebrew formula (default: packaging/homebrew/oz.rb)",
    )
    parser.add_argument(
        "--winget-template-dir",
        type=pathlib.Path,
        default=repo_root / "packaging/winget",
        help="Directory containing template winget manifests (default: packaging/winget)",
    )
    parser.add_argument(
        "--out-dir",
        type=pathlib.Path,
        help="Output directory; writes <out-dir>/oz.rb and <out-dir>/winget/OzoneVCS.Ozone*.yaml",
    )
    parser.add_argument(
        "--homebrew-out",
        type=pathlib.Path,
        help="Explicit output path for populated Homebrew formula",
    )
    parser.add_argument(
        "--winget-out-dir",
        type=pathlib.Path,
        help="Explicit output directory for populated winget manifests",
    )
    parser.add_argument(
        "--in-place",
        action="store_true",
        help="Update template manifests in place (for maintainer release PRs)",
    )

    args = parser.parse_args()

    version = (args.version or read_cargo_version(repo_root)).lstrip("v")
    if not VERSION_RE.fullmatch(version):
        raise SystemExit(f"error: invalid release version {version!r}")

    if args.in_place:
        if args.out_dir or args.homebrew_out or args.winget_out_dir:
            raise SystemExit("error: --in-place cannot be combined with --out-dir/--homebrew-out/--winget-out-dir")
        hb_out = args.homebrew_template
        wg_out = args.winget_template_dir
    else:
        hb_out = args.homebrew_out or (args.out_dir / "oz.rb" if args.out_dir else None)
        wg_out = args.winget_out_dir or (args.out_dir / "winget" if args.out_dir else None)
        if hb_out is None or wg_out is None:
            raise SystemExit(
                "error: specify --out-dir, both --homebrew-out and --winget-out-dir, or --in-place"
            )

    checksums = parse_checksums(args.checksums)
    hb_hashes, win_digest_upper = require_release_checksums(checksums, version)

    populate_homebrew(args.homebrew_template, hb_out, version, hb_hashes)
    populate_winget(args.winget_template_dir, wg_out, version, win_digest_upper)

    print(f"Populated release manifests for Ozone v{version}:")
    print(f"  Homebrew: {hb_out}")
    print(f"  winget:   {wg_out}/OzoneVCS.Ozone*.yaml")
    return 0


if __name__ == "__main__":
    sys.exit(main())
